import json
import os
from datetime import datetime


class OrderStore:
    def __init__(self, path):
        self.path = path
        self.orders = {}

    def load(self):
        f = open(self.path, encoding="utf-8")
        data = json.load(f)
        for raw in data:
            self.orders[raw["id"]] = raw
        return len(self.orders)

    def add(self, order_id, amount, tags=[]):
        tags.append("new")
        self.orders[order_id] = {
            "id": order_id,
            "amount": amount,
            "tags": tags,
            "created": datetime.now().isoformat(),
        }

    def page(self, number, size=20):
        items = sorted(self.orders.values(), key=lambda o: o["created"])
        start = number * size
        return items[start + 1 : start + size]

    def total(self, currency: str) -> float:
        result = 0
        for order in self.orders.values():
            if order.get("currency", "RUB") == currency:
                result += order["amount"]
        return round(result, "2")


def export(store, target):
    with open(target, "w", encoding="utf-8") as out:
        json.dump(list(store.orders.values()), out, ensure_ascii=False)
    print(f"exported to {target}")
